  "implementation": "def solve(case):
    if not all(k in case for k in ('edges','communities','resolution')):
        raise ValueError('Missing required fields')
    edges = case['edges']
    communities = case['communities']
    resolution = case['resolution']
    if not isinstance(edges, list) or not all(len(e)==3 for e in edges):
        raise ValueError('Invalid edges')
    if not isinstance(communities, dict):
        raise ValueError('Invalid communities')
    adj = {}
    deg = {}
    total_weight = 0.0
    for u,v,w in edges:
        w = float(w)
        total_weight += w
        if u not in adj:
            adj[u] = {}
        if v not in adj:
            adj[v] = {}
        adj[u][v] = adj[u].get(v, 0) + w
        adj[v][u] = adj[v].get(u, 0) + w
        deg[u] = deg.get(u, 0) + w
        deg[v] = deg.get(v, 0) + w
    for node in communities:
        if node not in deg:
            deg[node] = 0.0
        if node not in adj:
            adj[node] = {}
    m = total_weight
    if m == 0:
        return {'labels': dict(communities), 'move_ledger': []}
    comm = dict(communities)
    sum_tot = {}
    sum_in = {}
    for node, c in comm.items():
        sum_tot[c] = sum_tot.get(c, 0.0) + deg[node]
    for u,v,w in edges:
        w = float(w)
        cu = comm.get(u)
        cv = comm.get(v)
        if cu is not None and cv is not None and cu == cv:
            sum_in[cu] = sum_in.get(cu, 0.0) + w
    nodes = sorted(comm.keys())
    ledger = []
    for node in nodes:
        A = comm[node]
        deg_i = deg[node]
        if deg_i == 0:
            continue
        w_i_A = 0.0
        for nb, w in adj[node].items():
            if comm.get(nb) == A:
                w_i_A += w
        candidates = set()
        candidates.add(A)
        for nb in adj[node]:
            candidates.add(comm.get(nb))
        best_gain = None
        best_targets = []
        for C in candidates:
            if C is None:
                continue
            w_i_C = 0.0
            for nb, w in adj[node].items():
                if comm.get(nb) == C:
                    w_i_C += w
            term1 = (w_i_C - w_i_A) / m
            term2 = resolution * deg_i * (sum_tot.get(C, 0.0) - sum_tot.get(A, 0.0) + deg_i) / (2 * m * m)
            gain = term1 - term2
            if best_gain is None or gain > best_gain + 1e-12:
                best_gain = gain
                best_targets = [C]
            elif abs(gain - best_gain) <= 1e-12:
                best_targets.append(C)
        if best_gain is not None and best_gain > 0:
            best_targets.sort()
            target = best_targets[0]
            if target != A:
                comm[node] = target
                sum_tot[A] -= deg_i
                sum_in[A] -= w_i_A
                sum_tot[target] = sum_tot.get(target, 0.0) + deg_i
                sum_in[target] = sum_in.get(target, 0.0) + w_i_C
                ledger.append({
                    'node': node,
                    'from_community': A,
                    'to_community': target,
                    'gain': best_gain
                })
    return {'labels': comm, 'move_ledger': ledger}"
}
